import { createRoot } from 'react-dom/client';
import './index.css';
import * as React from 'react';
import { useEffect, useRef, useState } from 'react';
import { ButtonComponent } from '@syncfusion/ej2-react-buttons';
import { SidebarComponent, TreeViewComponent, BreadcrumbComponent, ToolbarComponent, ItemDirective, ItemsDirective, } from '@syncfusion/ej2-react-navigations';
import { BlockEditorComponent, } from '@syncfusion/ej2-react-blockeditor';
import { MarkdownConverter } from '@syncfusion/ej2-markdown-converter';
import TurndownService from 'turndown';
import { gfm } from 'turndown-plugin-gfm';


const MarkdownBlocks = () => {
    const sidebarRef = useRef(null);
    const treeviewRef = useRef(null);
    const blockEditorRef = useRef(null);
    const closeBtnRef = useRef(null);
    const downloadBtnRef = useRef(null);
    const [width] = useState('240px');
    const [enableDock] = useState(true);
    const [dockSize] = useState('33px');
    const [mediaQuery] = useState('(min-width: 600px)');
    const [target] = useState('.blockeditor-marked');
    const [markdownContent, setMarkdownContent] = useState('');
    const [sidebarHeaderText] = useState('Markdown Templates');
    const [breadcrumbItems, setBreadcrumbItems] = useState([{ text: 'Team' }]);
    const turndownServiceRef = React.useMemo(() => {
        const service = new TurndownService({
            codeBlockStyle: 'fenced',
            emDelimiter: '_',
            bulletListMarker: '-',
            headingStyle: 'atx'
        });
        service.use(gfm);
        return service;
    }, []);
    const customToolbarItems = [
        'Bold', 'Italic', 'Underline', 'Strikethrough'
    ];
    const inlineToolbar = {
        enable: true,
        items: customToolbarItems,
    };
    const commandItems = [
        {
            "id": "bullet-list-command",
            "type": "BulletList",
            "groupBy": "General",
            "label": "Bullet List",
            "tooltip": "Create a bullet list",
            "iconCss": "e-icons e-list-unordered",
            "shortcut": "Ctrl+Shift+8"
        },
        {
            "id": "numbered-list-command",
            "type": "NumberedList",
            "groupBy": "General",
            "label": "Numbered List",
            "tooltip": "Create a numbered list",
            "iconCss": "e-icons e-list-ordered",
            "shortcut": "Ctrl+Shift+9"
        },
        {
            "id": "divider-command",
            "type": "Divider",
            "groupBy": "General",
            "label": "Divider",
            "tooltip": "Add a horizontal line",
            "iconCss": "e-icons e-be-divider",
            "shortcut": "Ctrl+Shift+-"
        },
        {
            "id": "code-command",
            "type": "Code",
            "groupBy": "Insert",
            "label": "Code",
            "tooltip": "Insert a code block",
            "iconCss": "e-icons e-insert-code",
            "shortcut": "Ctrl+Alt+k"
        },
        {
            "id": "table-command",
            "type": "Table",
            "groupBy": "Insert",
            "label": "Table",
            "tooltip": "Insert a table block",
            "iconCss": "e-icons e-table-2",
            "shortcut": "Ctrl+Alt+T"
        },
        {
            "id": "paragraph-command",
            "type": "Paragraph",
            "groupBy": "Text Styles",
            "label": "Paragraph",
            "tooltip": "Add a paragraph",
            "iconCss": "e-icons e-be-paragraph",
            "shortcut": "Ctrl+Alt+P"
        },
        {
            "id": "heading1-command",
            "type": "Heading",
            "groupBy": "Text Styles",
            "label": "Heading 1",
            "tooltip": "Page title or main heading",
            "iconCss": "e-icons e-be-h1",
            "shortcut": "Ctrl+Alt+1"
        },
        {
            "id": "heading2-command",
            "type": "Heading",
            "groupBy": "Text Styles",
            "label": "Heading 2",
            "tooltip": "Section heading",
            "iconCss": "e-icons e-be-h2",
            "shortcut": "Ctrl+Alt+2"
        },
        {
            "id": "heading3-command",
            "type": "Heading",
            "groupBy": "Text Styles",
            "label": "Heading 3",
            "tooltip": "Subsection heading",
            "iconCss": "e-icons e-be-h3",
            "shortcut": "Ctrl+Alt+3"
        },
        {
            "id": "heading4-command",
            "type": "Heading",
            "groupBy": "Text Styles",
            "label": "Heading 4",
            "tooltip": "Smaller heading for nested content",
            "iconCss": "e-icons e-be-h4",
            "shortcut": "Ctrl+Alt+4"
        },
        {
            "id": "quote-command",
            "type": "Quote",
            "groupBy": "Text Styles",
            "label": "Quote",
            "tooltip": "Insert a quote block",
            "iconCss": "e-icons e-blockquote",
            "shortcut": "Ctrl+Alt+Q"
        }
    ];
    const data = [
        {
            id: 'Team_Sessions',
            name: 'Team Sessions',
            mdFile: 'https://ej2.syncfusion.com/react/demos/src/block-editor/mdfiles/Team%20Sessions.md',
            selected: true,
            expanded: true,
            children: [
                { id: '1', name: 'Meeting minutes.md', mdFile: 'https://ej2.syncfusion.com/react/demos/src/block-editor/mdfiles/Meeting%20minutes.md' },
                { id: '2', name: 'Brain storming.md', mdFile: 'https://ej2.syncfusion.com/react/demos/src/block-editor/mdfiles/Brain%20storming.md' },
                { id: '3', name: 'Retrospective.md', mdFile: 'https://ej2.syncfusion.com/react/demos/src/block-editor/mdfiles/Retrospective.md' },
            ]
        }
    ];
    const field = {
        dataSource: data,
        id: 'id',
        text: 'name',
        child: 'children'
    };
    const renderFallbackBlocks = (message) => {
        const fb = [{
                id: 'fallback-block',
                blockType: 'Paragraph',
                content: [{ id: 'fallback-t', contentType: 'Text', content: message }],
                properties: { placeholder: 'Fallback content' },
                indent: 0
            }];
        if (blockEditorRef.current) {
            blockEditorRef.current.renderBlocksFromJson(fb, true);
        }
    };
    const formatBreadcrumbText = (name) => {
        return name?.endsWith('.md') ? name.replace(/\.md$/i, '') : name;
    };
    const loadContent = async (mdFile) => {
        try {
            const res = await fetch(mdFile);
            if (!res.ok)
                throw new Error(`HTTP ${res.status}`);
            const text = await res.text();
            const html = MarkdownConverter.toHtml(text);
            setMarkdownContent(html);
            if (blockEditorRef.current && html) {
                try {
                    const nodeDatas = blockEditorRef.current.parseHtmlToBlocks(html);
                    blockEditorRef.current.renderBlocksFromJson(nodeDatas, true);
                }
                catch (parseErr) {
                    renderFallbackBlocks(`Parsed content from ${mdFile} failed.`);
                }
            }
        }
        catch (err) {
            renderFallbackBlocks(`Error loading ${mdFile}. Ensure file exists in /src/.`);
        }
    };
    const onOpen = () => {
        treeviewRef.current.expandAll();
        if (closeBtnRef.current?.element) {
            closeBtnRef.current.element.style.left = '225px';
            closeBtnRef.current.element.classList.remove('expand-mode');
        }
        if (treeviewRef.current?.element) {
            treeviewRef.current.element.style.display = 'block';
        }
    };
    const onClose = () => {
        if (closeBtnRef.current?.element) {
            closeBtnRef.current.element.style.left = '18px';
            closeBtnRef.current.element.classList.add('expand-mode');
        }
        if (treeviewRef.current?.element) {
            treeviewRef.current.element.style.display = 'none';
        }
    };
    const openClick = () => {
        sidebarRef.current?.toggle();
    };
    const downloadMarkdown = () => {
        if (!blockEditorRef.current) {
            return;
        }
        let htmlContent = '';
        try {
            htmlContent = blockEditorRef.current.getDataAsHtml();
        }
        catch (e) {
            return;
        }
        const markdownContent = turndownServiceRef.turndown(htmlContent || '');
        let fileName = 'document.md';
        const lastCrumb = breadcrumbItems?.[breadcrumbItems.length - 1]?.text;
        if (lastCrumb) {
            const safe = lastCrumb.replace(/[\\/:*?"<>|]+/g, '').trim() || 'document';
            fileName = `${safe}.md`;
        }
        const blob = new Blob([markdownContent], { type: 'text/markdown;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        try {
            a.href = url;
            a.download = fileName;
            document.body.appendChild(a);
            a.click();
        }
        finally {
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }
    };
    const onNodeSelected = (args) => {
        const selectedId = args?.nodeData?.id;
        if (selectedId === 'Team_Sessions') {
            setBreadcrumbItems([{ text: 'Team' }, { text: 'Team Sessions' }]);
            loadContent('https://ej2.syncfusion.com/react/demos/src/block-editor/mdfiles/Team%20Sessions.md');
            return;
        }
        const findNodeById = (nodes, id) => {
            for (const n of nodes) {
                if (n.id === id)
                    return n;
                if (n.children?.length) {
                    const found = findNodeById(n.children, id);
                    if (found)
                        return found;
                }
            }
            return undefined;
        };
        const selectedNode = findNodeById(data, selectedId);
        if (selectedNode?.mdFile) {
            loadContent(selectedNode.mdFile);
            const parentID = args?.nodeData?.parentID;
            const isUnderGuideline = !!parentID && parentID === 'Team_Sessions';
            if (isUnderGuideline) {
                setBreadcrumbItems([
                    { text: 'Team' },
                    { text: 'Team Sessions' },
                    { text: formatBreadcrumbText(selectedNode.name) }
                ]);
            }
            else {
                setBreadcrumbItems([
                    { text: 'Team' },
                    { text: formatBreadcrumbText(selectedNode.name) }
                ]);
            }
        }
    };
    useEffect(() => {
        setTimeout(() => {
            loadContent('https://ej2.syncfusion.com/react/demos/src/block-editor/mdfiles/Team%20Sessions.md');
            setBreadcrumbItems([{ text: 'Team' }, { text: 'Team Sessions' }]);
            if (closeBtnRef.current?.element && window.innerWidth < 600) {
                closeBtnRef.current.element.style.left = '18px';
                closeBtnRef.current.element.classList.add('expand-mode');
            }
        }, 100);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);
    return (<div className='control-pane'>
      <div className="control-section blockeditor-marked">
        <SidebarComponent id="sidebar-treeview" className="sidebar-content" ref={sidebarRef} enableDock={enableDock} width={width} enableGestures={false} dockSize={dockSize} open={onOpen} close={onClose} mediaQuery={mediaQuery} target={target} isOpen={false}>
          <div className="sidebar-header">
            <span>{sidebarHeaderText}</span>
          </div>

          <div className="sb-rightpane-collapsed">
            <div className="labelchoose">Markdown Templates</div>
          </div>

          <div className="main-menu">
            <ButtonComponent cssClass="e-btn e-round closebutton" iconCss="e-icons e-chevron-left" id="left-toc-closebtn" ref={closeBtnRef} onClick={openClick}/>
            <TreeViewComponent id="main-treeview" ref={treeviewRef} fields={field} expandOn="Click" nodeSelected={onNodeSelected}/>
          </div>
        </SidebarComponent>

        <div id="content_container" className="block-content">
          <div className="stick">
            <ToolbarComponent>
              <ItemsDirective>
                <ItemDirective align="Left" template={() => (<div className="breadcrumbcontent">
                    <BreadcrumbComponent items={breadcrumbItems} separatorTemplate={() => (<span className="e-icons e-chevron-right"></span>)}/>
                  </div>)}/>
                <ItemDirective align="Right" template={() => (<ButtonComponent ref={downloadBtnRef} iconCss="e-icons e-download" title="Download Markdown" className="downloadbutton" onClick={downloadMarkdown}/>)}/>
              </ItemsDirective>
            </ToolbarComponent>
          </div>

          <div className="markeditor">
            <BlockEditorComponent ref={blockEditorRef} height="597px" inlineToolbarSettings={inlineToolbar} commandMenuSettings={{
            popupWidth: '298px',
            popupHeight: '400px',
            commands: commandItems,
        }}/>
          </div>
        </div>
      </div>


    </div>);
};
export default MarkdownBlocks;

const root = createRoot(document.getElementById('sample'));
root.render(<MarkdownBlocks />);
